  "confidence": 0.95,
  "reason": "The alias diagnostic merely measures epistemic OOD variance across degenerate discrete transitions (e.g., wall bumps, no-op interactions), which is an established representation artifact of unconstrained neural transition functions rather than a security vulnerability. Across all checkpoints (base, WAV, Hard-Oracle, Random), split rates remain essentially invariant (~93.4%–96.7%), demonstrating that this metric reflects ambient baseline model noise rather than an exploitable, controllable vulnerability. Under black-box simulator constraints, an attacker triggering this split is indistinguishable from standard out-of-distribution state visitation causing compounding prediction error. Estimated probability of surviving ICLR peer review as a novel security claim is <5% due to direct overlap with action-semantic mismatch literature (arXiv:2610.06582) and symmetry/quotient MDP literature.",
  "mechanism": "None (rejected). Action alias splitting is an ambient representation defect, not an operationalized attack mechanism.",
  "experiment": "None (rejected).",
  "falsification_gate": "None (rejected).",
  "alternatives": [
    {
      "name": "Latent Horizon Collapse via Absorbing Dynamics Induction",
      "mechanism": "An online adversarial agent executes a legal action prefix that steers the victim world model's recurrent latent state into an artificial absorbing attractor basin, causing downstream MPC/imagination rollouts to prematurely collapse predicted state variance to zero and paralyze native planning depth without triggering high one-step reconstruction errors.",
      "falsification_gate": "Across 100 evaluation episodes in MiniGrid-DoorKey using a native MPC controller, an attacker-induced legal prefix must reduce controller planning horizon depth by >= 50% and task success rate by >= 35% compared to matched OOD trajectory controls while keeping 1-step latent prediction residual within 1.15x of nominal trajectories."
    },
    {
      "name": "Imagined Branch Hijacking via Value-Gradient Pinning",
      "mechanism": "The attacker exploits non-injective latent dynamics by executing an action sequence that forces the world model's internal rollout branches to hallucinate an unlocked goal state along all search paths, inducing native value-guided tree search to commit irreversible physical transitions into dead-ends.",
      "falsification_gate": "Across 50 distinct random MiniGrid seeds with a native closed-loop planner, the prefix must trick the controller into taking a catastrophic dead-end action with >= 40% probability while an observation-matched random exploration prefix causes <= 5% catastrophic commitment."
    }
  ]
}

